func (this *Coinex) fetchContractMarketsBody(ch chan any, params any) any {
	defer close(ch)
	defer ReturnPanicError(ch)

	response := (<-this.V2PublicGetFuturesMarket(params))
	PanicOnError(response)
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "base_ccy": "BTC",
	//                 "base_ccy_precision": 8,
	//                 "contract_type": "inverse",
	//                 "leverage": ["1","2","3","5","8","10","15","20","30","50","100"],
	//                 "maker_fee_rate": "0",
	//                 "market": "BTCUSD",
	//                 "min_amount": "10",
	//                 "open_interest_volume": "2566879",
	//                 "quote_ccy": "USD",
	//                 "quote_ccy_precision": 2,
	//                 "taker_fee_rate": "0"
	//             },
	//         ],
	//         "message": "OK"
	//     }
	//
	var markets any = this.SafeList(response, "data", []any{})
	var result any = []any{}
	for i := 0; IsLessThan(i, GetArrayLength(markets)); i++ {
		var entry any = GetValue(markets, i)
		var fees any = this.Fees
		var leverages any = this.SafeList(entry, "leverage", []any{})
		var subType any = this.SafeString(entry, "contract_type")
		var linear bool = (IsEqual(subType, "linear"))
		var inverse bool = (IsEqual(subType, "inverse"))
		var id any = this.SafeString(entry, "market")
		var baseId any = this.SafeString(entry, "base_ccy")
		var quoteId any = this.SafeString(entry, "quote_ccy")
		var base any = this.SafeCurrencyCode(baseId)
		var quote any = this.SafeCurrencyCode(quoteId)
		var settleId any = Ternary(IsTrue((IsEqual(subType, "linear"))), "USDT", baseId)
		var settle any = this.SafeCurrencyCode(settleId)
		var symbol any = Add(Add(Add(Add(base, "/"), quote), ":"), settle)
		var leveragesLength int = GetArrayLength(leverages)
		AppendToArray(&result, map[string]any{
			"id":             id,
			"symbol":         symbol,
			"base":           base,
			"quote":          quote,
			"settle":         settle,
			"baseId":         baseId,
			"quoteId":        quoteId,
			"settleId":       settleId,
			"type":           "swap",
			"spot":           false,
			"margin":         false,
			"swap":           true,
			"future":         false,
			"option":         false,
			"active":         nil,
			"contract":       true,
			"linear":         linear,
			"inverse":        inverse,
			"taker":          GetValue(GetValue(fees, "trading"), "taker"),
			"maker":          GetValue(GetValue(fees, "trading"), "maker"),
			"contractSize":   this.ParseNumber("1"),
			"expiry":         nil,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"precision": map[string]any{
				"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(entry, "base_ccy_precision"))),
				"price":  this.ParseNumber(this.ParsePrecision(this.SafeString(entry, "quote_ccy_precision"))),
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": this.SafeNumber(leverages, 0),
					"max": this.SafeNumber(leverages, Subtract(leveragesLength, 1)),
				},
				"amount": map[string]any{
					"min": this.SafeNumber(entry, "min_amount"),
					"max": nil,
				},
				"price": map[string]any{
					"min": nil,
					"max": nil,
				},
				"cost": map[string]any{
					"min": nil,
					"max": nil,
				},
			},
			"created": nil,
			"info":    entry,
		})
	}

	ch <- result
	return nil
}
func (this *Coinex) ParseTicker(ticker any, optionalArgs ...any) any {
	//
	// Spot fetchTicker, fetchTickers
	//
	//     {
	//         "close": "62393.47",
	//         "high": "64106.41",
	//         "last": "62393.47",
	//         "low": "59650.01",
	//         "market": "BTCUSDT",
	//         "open": "61616.15",
	//         "period": 86400,
	//         "value": "28711273.4065667262",
	//         "volume": "461.76557205",
	//         "volume_buy": "11.41506354",
	//         "volume_sell": "7.3240169"
	//     }
	//
	// Swap fetchTicker, fetchTickers
	//
	//     {
	//         "close": "62480.08",
	//         "high": "64100",
	//         "index_price": "62443.05",
	//         "last": "62480.08",
	//         "low": "59600",
	//         "mark_price": "62443.05",
	//         "market": "BTCUSDT",
	//         "open": "61679.98",
	//         "period": 86400,
	//         "value": "180226025.69791713065326633165",
	//         "volume": "2900.2218",
	//         "volume_buy": "7.3847",
	//         "volume_sell": "6.1249"
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketType any = Ternary(IsTrue((InOp(ticker, "mark_price"))), "swap", "spot")
	var marketId any = this.SafeString(ticker, "market")
	market = this.SafeMarket(marketId, market, nil, marketType)
	var symbol any = GetValue(market, "symbol")
	// on inverse contracts 'value' is denominated in the settle currency, not
	// the quote, so it is the quote volume only for spot and linear markets
	var quoteVolume any = Ternary(IsTrue((IsEqual(GetValue(market, "inverse"), true))), nil, this.SafeString(ticker, "value"))
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     nil,
		"datetime":      nil,
		"high":          this.SafeString(ticker, "high"),
		"low":           this.SafeString(ticker, "low"),
		"bid":           nil,
		"bidVolume":     this.SafeString(ticker, "volume_buy"),
		"ask":           nil,
		"askVolume":     this.SafeString(ticker, "volume_sell"),
		"vwap":          nil,
		"open":          this.SafeString(ticker, "open"),
		"close":         this.SafeString(ticker, "close"),
		"last":          this.SafeString(ticker, "last"),
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       nil,
		"baseVolume":    this.SafeString(ticker, "volume"),
		"quoteVolume":   quoteVolume,
		"markPrice":     this.SafeString(ticker, "mark_price"),
		"indexPrice":    this.SafeString(ticker, "index_price"),
		"info":          ticker,
	}, market)
}

