func (this *Coinex) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// Spot and Swap fetchTrades (public)
	//
	//     {
	//         "amount": "0.00049432",
	//         "created_at": 1713849825667,
	//         "deal_id": 4137517302,
	//         "price": "66251",
	//         "side": "buy"
	//     }
	//
	// Spot and Margin fetchMyTrades (private)
	//
	//     {
	//         "amount": "0.00010087",
	//         "created_at": 1714618087585,
	//         "deal_id": 4161200602,
	//         "margin_market": "",
	//         "market": "BTCUSDT",
	//         "order_id": 117654919342,
	//         "price": "57464.04",
	//         "side": "sell"
	//     }
	//
	// Swap fetchMyTrades (private)
	//
	//     {
	//         "deal_id": 1180222387,
	//         "created_at": 1714119054558,
	//         "market": "BTCUSDT",
	//         "side": "buy",
	//         "order_id": 136915589622,
	//         "price": "64376",
	//         "amount": "0.0001",
	//         "role": "taker",
	//         "fee": "0.0299",
	//         "fee_ccy": "USDT"
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var timestamp any = this.SafeInteger(trade, "created_at")
	var defaultType any = this.SafeString(this.Options, "defaultType")
	if IsTrue(!IsEqual(market, nil)) {
		defaultType = GetValue(market, "type")
	}
	var marketId any = this.SafeString(trade, "market")
	market = this.SafeMarket(marketId, market, nil, defaultType)
	var feeCostString any = this.SafeString(trade, "fee")
	var fee any = nil
	if IsTrue(!IsEqual(feeCostString, nil)) {
		var feeCurrencyId any = this.SafeString(trade, "fee_ccy")
		var feeCurrencyCode any = this.SafeCurrencyCode(feeCurrencyId)
		fee = map[string]any{
			"cost":     feeCostString,
			"currency": feeCurrencyCode,
		}
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       GetValue(market, "symbol"),
		"id":           this.SafeString(trade, "deal_id"),
		"order":        this.SafeString(trade, "order_id"),
		"type":         nil,
		"side":         this.SafeString(trade, "side"),
		"takerOrMaker": this.SafeString(trade, "role"),
		"price":        this.SafeString(trade, "price"),
		"amount":       this.SafeString(trade, "amount"),
		"cost":         this.SafeString(trade, "deal_money"),
		"fee":          fee,
	}, market)
}

