func (this *Coinex) fetchOHLCVBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	timeframe := GetArg(optionalArgs, 0, "1m")
	_ = timeframe
	since := GetArg(optionalArgs, 1, nil)
	_ = since
	limit := GetArg(optionalArgs, 2, nil)
	_ = limit
	params := GetArg(optionalArgs, 3, map[string]any{})
	_ = params
	if IsTrue(IsEqual(this.Markets, nil)) {

		retRes166812 := (<-this.LoadMarketsAsync())
		PanicOnError(retRes166812)
	}
	var market any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"market": GetValue(market, "id"),
		"period": this.SafeString(this.Timeframes, timeframe, timeframe),
	}
	if IsTrue(!IsEqual(limit, nil)) {
		AddElementToObject(request, "limit", limit)
	}
	var response any = nil
	if IsTrue(IsEqual(GetValue(market, "swap"), true)) {

		response = (<-this.V2PublicGetFuturesKline(this.Extend(request, params)))
		PanicOnError(response)
	} else {

		response = (<-this.V2PublicGetSpotKline(this.Extend(request, params)))
		PanicOnError(response)
	}
	//
	// Spot and Swap
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "close": "66999.95",
	//                 "created_at": 1713934620000,
	//                 "high": "66999.95",
	//                 "low": "66988.53",
	//                 "market": "BTCUSDT",
	//                 "open": "66988.53",
	//                 "value": "0.1572393",
	//                 "volume": "10533.2501364336"
	//             },
	//         ],
	//         "message": "OK"
	//     }
	//
	var data any = this.SafeList(response, "data", []any{})

	ch <- this.ParseOHLCVs(data, market, timeframe, since, limit)
	return nil
}
